const KEY_FILL = { light: '#5a3fc0', dark: '#7b5ee0' };
const GOLD = '#e8a400';
const SUN = '#ffd23c';
const LOTUS = 'M12 4c2 2.2 3 4.6 3 7.2 0 1.8-1.1 3.6-3 4.8-1.9-1.2-3-3-3-4.8C9 8.6 10 6.2 12 4zM3 10.5c2.6-.3 5 .5 6.8 '
