const KEY = 'M24 0A24 24 0 1 0 24 48A24 24 0 1 0 24 0Z M17.77 23.23L21.44 26.89L30.17 17.29A1.8 1.8 0 0 1 32.83 '
  + '19.71L22.83 30.71A1.8 1.8 0 0 1 20.23 30.77L15.23 25.77A1.8 1.8 0 0 1 17.77 23.23Z';

// A lotus in two soft rings, as the prototype breathes it; gold once today is done.
function breathe(done, u) {
  const ring = done ? SUN : { light: '#5a3fc0', dark: '#c4b0ff' };
  return { type: 'zstack', frame: { width: 60 * u, height: 60 * u }, children: [
    { type: 'circle', fill: ring, opacity: done ? 0.35 : 0.12 },
    { type: 'circle', fill: ring, opacity: done ? 0.35 : 0.2, padding: 10 * u },
    { type: 'path', d: LOTUS, viewBox: [0, 0, 24, 24], fill: done ? GOLD : VIOLET, frame: { width: 26 * u, height: 26 * u } },
  ] };
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size, so
  // the gaps around the count are 0.1 of its size shorter than the prototype's.
  const u = ctx.height / 170;
  const d = ctx.data;
  const done = !!d.today;

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    // The check is cut out of the key, so a white disc under it in the backdrop shows through the cut in full
    // color; tinted and clear mode remove the backdrop and the cut still shows.
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: LAVENDER,
      children: [{ type: 'zstack', padding: 13 * u,
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomTrailing' },
        children: [{ type: 'circle', fill: '#FFFFFF', padding: 10 * u, frame: { width: 46 * u, height: 46 * u } }] }] },
    children: [
      { type: 'zstack', padding: { top: 12 * u, trailing: 12 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topTrailing' },
        children: [breathe(done, u)] },
      { type: 'vstack', align: 'leading', spacing: 0,
        padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: LOTUS, viewBox: [0, 0, 24, 24], fill: VIOLET, frame: { width: 15 * u, height: 15 * u } },
            { type: 'text', value: 'Meditate', size: 13 * u, weight: 'bold', color: VIOLET, lineLimit: 1 } ] },
          { type: 'text', value: d.streak, fontName: 'Bricolage Grotesque Display', size: 44 * u, kerning: -1.32 * u,
            color: WORDS, accent: true, lineLimit: 1, minScale: 0.5, padding: { top: 3.6 * u },
            frame: { maxWidth: ctx.width - 100 * u, alignment: 'leading' } },
          { type: 'text', value: done ? 'day streak,' : 'day streak', size: 12.5 * u, weight: 'semibold',
            color: WORDS, opacity: 0.8, padding: { top: 0.6 * u } },
          done && { type: 'text', value: 'done today', size: 12.5 * u, weight: 'semibold', color: WORDS, opacity: 0.8 },
        ] },
      { type: 'zstack', padding: 13 * u,
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomTrailing' },
        children: [
          { type: 'button', action: done ? 'undo' : 'done', rowId: done ? d.today.id : null, children: [
            { type: 'path', d: KEY, viewBox: [0, 0, 48, 48], fill: KEY_FILL, accent: true,
              frame: { width: 46 * u, height: 46 * u }, shadow: { color: '#0000004D', radius: 5 * u, y: 4 * u } } ] },
        ] },
    ],
  };
}
